// Nativelet Voice Recorder. MIT: retain the accompanying LICENSE.
import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, Pressable, Text, View, type ViewStyle } from "react-native";
import { Canvas, Circle, Group, Path, Points, RoundedRect } from "@shopify/react-native-skia";
import Animated, { useAnimatedStyle, useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import {
  BAR_COUNT, BAR_H, BAR_W, BAR_X, BAR_Y, LOCK_CX, LOCK_CY, LOCK_H, LOCK_W, MIC_CX, MIC_CY, MIC_R,
  REC_H, REC_W, TIMER_X, WAVE_CY, DOT_X, barSegment, cancelWash, clamp01, createRecorder,
  recorderLockedCancel, recorderLockedSend, recorderPressEnd, recorderPressMove, recorderPressStart,
  stepRecorder, formatClock, type RecorderEvent, type RecorderPhase, type RecorderState,
} from "./recorderMath";
import {
  REC_BAR_BG, REC_BAR_BORDER, REC_GREEN, REC_GREEN_SOFT, REC_RED, REC_RED_SOFT, REC_TEXT_FAINT, REC_WAVE,
} from "./recorderDesign";

export type VoiceMessage = { seconds: number; samples: number[] };

export type VoiceRecorderProps = {
  onSend?: (message: VoiceMessage) => void;
  onCancel?: () => void;
  onFeedback?: (event: "touch" | "start" | "lock" | "cancel" | "send") => void;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  label?: string;
  style?: ViewStyle;
};

// Android stops presenting a canvas whose only change is internal on an idle
// screen. A 1 px layout change every frame keeps it drawing.
function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

function barsToPoints(s: RecorderState): { x: number; y: number }[] {
  'worklet';
  const wash = cancelWash(s);
  const out: { x: number; y: number }[] = [];
  for (let i = 0; i < BAR_COUNT; i++) {
    const seg = barSegment(s, i);
    out.push({ x: seg.x + wash.dx, y: seg.y0 }, { x: seg.x + wash.dx, y: seg.y1 });
  }
  return out;
}

function Waveform({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const points = useDerivedValue(() => {
    frame.value;
    return barsToPoints(sim.value);
  });
  const opacity = useDerivedValue(() => {
    const s = sim.value;
    if (s.phase === "idle" || s.phase === "pressing") return 0;
    if (s.phase === "sending" || s.phase === "cancelling") return 1 - clamp01(s.anim);
    return 1;
  });
  return (
    <Group opacity={opacity}>
      <Points points={points} mode="lines" color={REC_WAVE} style="stroke" strokeWidth={2.6} strokeCap="round" />
    </Group>
  );
}

function RecordDot({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const opacity = useDerivedValue(() => {
    frame.value;
    const s = sim.value;
    if (s.phase === "idle" || s.phase === "pressing") return 0;
    if (s.phase === "sending" || s.phase === "cancelling") return 1 - clamp01(s.anim);
    return 0.55 + 0.45 * Math.sin(s.t * 4.2);
  });
  return <Circle cx={DOT_X} cy={MIC_CY} r={5} color={REC_RED} opacity={opacity} />;
}

function LockCapsule({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const opacity = useDerivedValue(() => {
    frame.value;
    const s = sim.value;
    if (s.phase === "pressing") return 0.4;
    if (s.phase === "recording") return 1;
    return 0;
  });
  const fill = useDerivedValue(() => {
    frame.value;
    return sim.value.lock;
  });
  const transform = useDerivedValue(() => {
    frame.value;
    return [{ translateX: LOCK_CX }, { translateY: LOCK_CY }, { scale: 1 + sim.value.lockPop * 0.35 }];
  });
  return (
    <Group opacity={opacity} transform={transform}>
      <RoundedRect x={-LOCK_W / 2} y={-LOCK_H / 2} width={LOCK_W} height={LOCK_H} r={22} color={REC_GREEN} opacity={0.12} />
      <RoundedRect x={-LOCK_W / 2 + 4} y={-LOCK_H / 2 + 4} width={LOCK_W - 8} height={LOCK_H - 8} r={18} color={REC_BAR_BG} />
      <LockFill fill={fill} />
      <Group transform={[{ translateY: -LOCK_H / 2 + 15 }]}>
        <Path path="M -5 4 L 0 -2 L 5 4" color={REC_TEXT_FAINT} style="stroke" strokeWidth={2} strokeCap="round" strokeJoin="round" />
      </Group>
      <Group transform={[{ translateY: LOCK_H / 2 - 21 }]}>
        <Path path="M -4.5 0 L -4.5 -3.5 A 4.5 4.5 0 0 1 4.5 -3.5 L 4.5 0" color={REC_GREEN} style="stroke" strokeWidth={1.8} strokeCap="round" />
        <RoundedRect x={-7} y={0} width={14} height={11} r={3} color={REC_GREEN} />
      </Group>
    </Group>
  );
}

function LockFill({ fill }: { fill: { value: number } }) {
  const height = useDerivedValue(() => (LOCK_H - 8) * fill.value);
  const y = useDerivedValue(() => LOCK_H / 2 - 4 - height.value);
  const r = useDerivedValue(() => Math.min(18, height.value / 2));
  return <RoundedRect x={-LOCK_W / 2 + 4} y={y} width={LOCK_W - 8} height={height} r={r} color={REC_GREEN_SOFT} />;
}

function MicGlyph({ sending }: { sending: { value: number } }) {
  // Mic: capsule + cradle arc + stem. Fades into a check while sending.
  const micOpacity = useDerivedValue(() => 1 - sending.value);
  const checkOpacity = useDerivedValue(() => sending.value);
  return (
    <Group>
      <Group opacity={micOpacity}>
        <RoundedRect x={-5} y={-10} width={10} height={15} r={5} color="#ffffff" />
        <Path path="M -8.5 -2 A 8.5 8.5 0 0 0 8.5 -2" color="#ffffff" style="stroke" strokeWidth={1.9} strokeCap="round" />
        <Path path="M 0 6.5 L 0 10 M -4.5 10 L 4.5 10" color="#ffffff" style="stroke" strokeWidth={1.9} strokeCap="round" />
      </Group>
      <Group opacity={checkOpacity}>
        <Path path="M -7 0.5 L -2.5 5 L 7 -4.5" color="#ffffff" style="stroke" strokeWidth={2.6} strokeCap="round" strokeJoin="round" />
      </Group>
    </Group>
  );
}

function TrashGlyph() {
  return (
    <Group>
      <RoundedRect x={-4.5} y={-3} width={9} height={9} r={1.6} color="transparent" style="stroke" strokeWidth={1.6} />
      <Path path="M -6 -5 L 6 -5 M -2.2 -5 L -2.2 -7 L 2.2 -7 L 2.2 -5 M -1.6 -0.5 L -1.6 3.5 M 1.6 -0.5 L 1.6 3.5" color={REC_RED} style="stroke" strokeWidth={1.6} strokeCap="round" />
    </Group>
  );
}

function MicButton({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const transform = useDerivedValue(() => {
    frame.value;
    return [{ translateX: MIC_CX }, { translateY: MIC_CY }, { scale: sim.value.micScale }];
  });
  const sending = useDerivedValue(() => {
    frame.value;
    return sim.value.phase === "sending" ? clamp01(sim.value.anim * 1.6) : 0;
  });
  const redOpacity = useDerivedValue(() => {
    frame.value;
    return sim.value.phase === "cancelling" ? 1 : 0;
  });
  return (
    <Group transform={transform}>
      <Circle cx={0} cy={0} r={MIC_R} color={REC_GREEN} />
      <Circle cx={0} cy={0} r={MIC_R} color={REC_RED} opacity={redOpacity} />
      <MicGlyph sending={sending} />
    </Group>
  );
}

function CancelChevrons({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const opacity = useDerivedValue(() => {
    frame.value;
    const s = sim.value;
    if (s.phase !== "recording" && s.phase !== "pressing") return 0;
    return clamp01(1 - s.cancel * 1.6) * 0.9;
  });
  return (
    <Group opacity={opacity} transform={[{ translateX: TIMER_X + 52 }, { translateY: MIC_CY }]}>
      <Path path="M 3 -5 L -3 0 L 3 5" color={REC_TEXT_FAINT} style="stroke" strokeWidth={2} strokeCap="round" strokeJoin="round" />
      <Path path="M 3 -5 L -3 0 L 3 5" color={REC_TEXT_FAINT} style="stroke" strokeWidth={2} strokeCap="round" strokeJoin="round" opacity={0.5} transform={[{ translateX: 9 }]} />
    </Group>
  );
}

function RedWash({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const opacity = useDerivedValue(() => {
    frame.value;
    return cancelWash(sim.value).alpha;
  });
  return <RoundedRect x={BAR_X} y={BAR_Y} width={BAR_W} height={BAR_H} r={30} color={REC_RED} opacity={opacity} />;
}

function LockedGlyphs({ sim, frame }: { sim: { value: RecorderState }; frame: { value: number } }) {
  const opacity = useDerivedValue(() => {
    frame.value;
    return sim.value.phase === "locked" ? 1 : 0;
  });
  return (
    <Group opacity={opacity}>
      <Group transform={[{ translateX: BAR_X + 34 }, { translateY: MIC_CY }]}>
        <Circle cx={0} cy={0} r={20} color={REC_RED_SOFT} />
        <TrashGlyph />
      </Group>
    </Group>
  );
}

function CancelHint({ sim }: { sim: { value: RecorderState } }) {
  const style = useAnimatedStyle(() => ({
    opacity: clamp01(1 - sim.value.cancel * 1.6),
    transform: [{ translateX: -sim.value.cancel * 28 }],
  }));
  return (
    <Animated.Text pointerEvents="none" style={[{ position: "absolute", left: TIMER_X + 66, top: MIC_CY - 8, color: REC_TEXT_FAINT, fontSize: 12 }, style]}>
      slide to cancel
    </Animated.Text>
  );
}

export function VoiceRecorder({
  onSend,
  onCancel,
  onFeedback,
  slowMotion = false,
  reducedMotion,
  label,
  style,
}: VoiceRecorderProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const sim = useSharedValue<RecorderState>(createRecorder());
  const frame = useSharedValue(0);
  const slowM = useSharedValue(false);
  const [ui, setUi] = useState<{ phase: RecorderPhase; seconds: number }>({ phase: "idle", seconds: 0 });
  const latest = useRef({ reduce, onSend, onCancel, onFeedback });
  latest.current.reduce = reduce;
  latest.current.onSend = onSend;
  latest.current.onCancel = onCancel;
  latest.current.onFeedback = onFeedback;

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    sim.value.reduced = reduce;
  }, [reduce, sim]);

  // Mirror coarse UI (phase + whole seconds) and drain sim events into the
  // callbacks. Polling on a light interval keeps the worklet loop free of
  // runOnJS chatter; the frame clock above drives the fine animation.
  useEffect(() => {
    const id = setInterval(() => {
      const s = sim.value;
      if (s.events.length) {
        const events = s.events.splice(0, s.events.length) as RecorderEvent[];
        for (const ev of events) {
          if (ev.type === "start") latest.current.onFeedback?.("start");
          else if (ev.type === "lock") latest.current.onFeedback?.("lock");
          else if (ev.type === "cancel") {
            latest.current.onCancel?.();
            latest.current.onFeedback?.("cancel");
          } else {
            latest.current.onSend?.({ seconds: ev.seconds, samples: ev.samples });
            latest.current.onFeedback?.("send");
          }
        }
      }
      setUi((prev) => {
        const seconds = Math.floor(s.seconds);
        return prev.phase === s.phase && prev.seconds === seconds ? prev : { phase: s.phase, seconds };
      });
    }, 80);
    return () => clearInterval(id);
  }, [sim]);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: (evt) => {
          if (sim.value.phase !== "idle") return false;
          return evt.nativeEvent.locationX > MIC_CX - MIC_R - 14;
        },
        onPanResponderTerminationRequest: () => false,
        onPanResponderGrant: () => {
          recorderPressStart(sim.value);
          latest.current.onFeedback?.("touch");
        },
        onPanResponderMove: (evt, gesture) => {
          recorderPressMove(sim.value, gesture.dx, gesture.dy);
        },
        onPanResponderRelease: () => {
          recorderPressEnd(sim.value);
        },
        onPanResponderTerminate: () => {
          recorderPressEnd(sim.value);
        },
      }),
    [sim],
  );

  useFrameCallback((info) => {
    const s = sim.value;
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    stepRecorder(s, dt * (slowM.value ? 0.25 : 1));
    frame.value = frame.value + 1;
  });

  const recording = ui.phase === "recording" || ui.phase === "locked" || ui.phase === "cancelling" || ui.phase === "sending";
  const defaultLabel = recording
    ? `Recording voice message, ${formatClock(ui.seconds)}. Slide left to cancel or drag up to lock.`
    : "Voice message button. Press and hold to record, slide left to cancel, drag up to lock. Tap to record hands free.";

  return (
    <View style={[{ width: REC_W, height: REC_H }, style]} accessibilityRole="button" accessibilityLabel={label ?? defaultLabel} {...pan.panHandlers}>
      <CanvasKeepAlive />
      <Canvas pointerEvents="none" style={{ width: REC_W, height: REC_H }}>
        <RoundedRect x={BAR_X} y={BAR_Y} width={BAR_W} height={BAR_H} r={30} color={REC_BAR_BG} />
        <RoundedRect x={BAR_X} y={BAR_Y} width={BAR_W} height={BAR_H} r={30} color={REC_BAR_BORDER} style="stroke" strokeWidth={1} />
        <RedWash sim={sim} frame={frame} />
        <RecordDot sim={sim} frame={frame} />
        <Waveform sim={sim} frame={frame} />
        <CancelChevrons sim={sim} frame={frame} />
        <LockedGlyphs sim={sim} frame={frame} />
        <MicButton sim={sim} frame={frame} />
        <LockCapsule sim={sim} frame={frame} />
      </Canvas>
      {ui.phase === "idle" || ui.phase === "pressing" ? (
        <Text pointerEvents="none" style={{ position: "absolute", left: BAR_X + 22, top: MIC_CY - 9, color: REC_TEXT_FAINT, fontSize: 15 }}>
          Message
        </Text>
      ) : null}
      {recording && ui.phase !== "sending" && ui.phase !== "cancelling" ? (
        <Text pointerEvents="none" style={{ position: "absolute", left: TIMER_X, top: MIC_CY - 8, color: "#1d2b23", fontSize: 13, fontVariant: ["tabular-nums"] }}>
          {formatClock(ui.seconds)}
        </Text>
      ) : null}
      {ui.phase === "recording" ? <CancelHint sim={sim} /> : null}
      {ui.phase === "locked" ? (
        <>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Discard recording"
            onPress={() => recorderLockedCancel(sim.value)}
            style={{ position: "absolute", left: BAR_X + 34 - 24, top: MIC_CY - 24, width: 48, height: 48 }}
            hitSlop={6}
          />
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Send voice message"
            onPress={() => recorderLockedSend(sim.value)}
            style={{ position: "absolute", left: MIC_CX - 26, top: MIC_CY - 26, width: 52, height: 52 }}
            hitSlop={6}
          />
        </>
      ) : null}
    </View>
  );
}

export default VoiceRecorder;

// Nativelet Voice Recorder. MIT: retain the accompanying LICENSE.
//
// Pure state machine + simulated audio model for a chat voice-recording
// bar. No React, no Skia: the native component, the Canvas2D web preview
// and the unit tests all step the same state, so every surface draws the
// same frame for the same input.
//
// Geometry: one light chat bar near the bottom of the canvas, a round mic
// button at its right end, and a lock capsule floating above the mic. The
// message thread above the bar is owned by the caller (Example / preview),
// fed by the "send" event's duration and samples.

export const REC_W = 360;
export const REC_H = 152; // bar row + lock capsule zone above it
export const BAR_X = 8;
export const BAR_Y = REC_H - 68;
export const BAR_W = REC_W - 16;
export const BAR_H = 60;
export const MIC_R = 22;
export const MIC_CX = BAR_X + BAR_W - MIC_R - 8;
export const MIC_CY = BAR_Y + BAR_H / 2;
export const LOCK_W = 44;
export const LOCK_H = 66;
export const LOCK_CX = MIC_CX;
export const LOCK_CY = 40;

export const DOT_X = BAR_X + 26; // record dot center
export const TIMER_X = BAR_X + 44; // timer left edge (text drawn by caller)
export const WAVE_X0 = BAR_X + 104; // waveform span
export const WAVE_X1 = MIC_CX - MIC_R - 12;
export const WAVE_CY = MIC_CY;
export const BAR_COUNT = 34;
export const BAR_SAMPLE_S = 0.09;

export const PRESS_DELAY_S = 0.22; // hold this long to start recording
export const CANCEL_DISTANCE = 120; // px dragged left for a full cancel
export const LOCK_DISTANCE = 76; // px dragged up to lock
export const MAX_SECONDS = 120; // recordings cap here and auto-send
export const SEND_ANIM_S = 0.5;
export const CANCEL_ANIM_S = 0.42;

export const clamp01 = (v: number) => {
  'worklet';
  return v < 0 ? 0 : v > 1 ? 1 : v;
};
export const lerp = (a: number, b: number, f: number) => {
  'worklet';
  return a + (b - a) * f;
};
export const smooth = (f: number) => {
  'worklet';
  return f * f * (3 - 2 * f);
};

export function formatClock(seconds: number): string {
  'worklet';
  const s = Math.max(0, Math.floor(seconds));
  const m = Math.floor(s / 60);
  return `${m}:${String(s % 60).padStart(2, "0")}`;
}

// Deterministic 1D value noise, hashed per integer cell, so native and web
// agree on every sample without sharing a random source.
function cellNoise(n: number, seed: number): number {
  'worklet';
  let x = (n | 0) * 2654435761 + seed * 40503;
  x = Math.imul(x ^ (x >>> 15), 2246822519);
  x = Math.imul(x ^ (x >>> 13), 3266489917);
  x ^= x >>> 16;
  return (x >>> 0) / 4294967296;
}

// Simulated voice level, 0..1. A syllable train (140 ms cells, smoothed)
// gated by a slow phrase envelope so the waveform breathes like speech:
// bursts, gaps, emphasis. Continuous in t. This is not microphone input.
export function levelAt(t: number, seed = 7): number {
  'worklet';
  if (t <= 0) return 0.08;
  const cell = t / 0.14;
  const i = Math.floor(cell);
  const f = smooth(cell - i);
  const a = cellNoise(i, seed);
  const b = cellNoise(i + 1, seed);
  const syllable = lerp(a, b, f);
  const gate = clamp01(0.62 + 0.42 * Math.sin(t * 1.9 + Math.sin(t * 0.63) * 2.2));
  const jitter = 0.82 + 0.18 * Math.sin(t * 43 + syllable * 11);
  return clamp01(0.06 + syllable * gate * jitter * 0.96);
}

export type RecorderPhase = "idle" | "pressing" | "recording" | "locked" | "cancelling" | "sending";

export type RecorderEvent =
  | { type: "start" }
  | { type: "lock" }
  | { type: "cancel"; seconds: number }
  | { type: "send"; seconds: number; samples: number[] };

export type RecorderState = {
  phase: RecorderPhase;
  t: number; // total sim seconds, always advancing
  pressAt: number; // t of the current press start, -1 when none
  recAt: number; // t when the current recording started
  seconds: number; // length of the current recording
  cancel: number; // 0..1 slide-to-cancel fill
  lock: number; // 0..1 drag-to-lock fill
  bars: number[]; // visible waveform ring, newest last, length BAR_COUNT
  levels: number[]; // every sample of the current recording, for the message
  lastSample: number; // recording-time of the last pushed sample
  anim: number; // 0..1 progress of the cancelling/sending morph
  micScale: number; // springed mic scale
  micVel: number;
  lockPop: number; // springed capsule scale on lock
  lockPopVel: number;
  events: RecorderEvent[];
  reduced: boolean;
  seed: number;
};

export function createRecorder(seed = 7): RecorderState {
  'worklet';
  return {
    phase: "idle",
    t: 0,
    pressAt: -1,
    recAt: 0,
    seconds: 0,
    cancel: 0,
    lock: 0,
    bars: new Array(BAR_COUNT).fill(0.07),
    levels: [],
    lastSample: 0,
    anim: 0,
    micScale: 1,
    micVel: 0,
    lockPop: 0,
    lockPopVel: 0,
    events: [],
    reduced: false,
    seed,
  };
}

function spring(x: number, v: number, target: number, dt: number, k: number, c: number): [number, number] {
  'worklet';
  const nv = (v + (target - x) * k * dt) * Math.exp(-c * dt);
  return [x + nv * dt, nv];
}

// Finger goes down on the mic. From idle only; locked recordings are ended
// through the on-bar Send and Cancel controls, not by touching the bar.
export function recorderPressStart(s: RecorderState): void {
  'worklet';
  if (s.phase !== "idle") return;
  s.phase = "pressing";
  s.pressAt = s.t;
  s.cancel = 0;
  s.lock = 0;
}

// dx/dy are the finger's displacement from the press point. The dominant
// axis wins: further left fills cancel, further up fills lock. Crossing the
// lock distance locks immediately, mid-gesture, like the chat apps do.
export function recorderPressMove(s: RecorderState, dx: number, dy: number): void {
  'worklet';
  if (s.phase !== "pressing" && s.phase !== "recording") return;
  if (-dy > -dx) {
    s.lock = clamp01(-dy / LOCK_DISTANCE);
    s.cancel = clamp01(s.cancel - 0.12);
  } else {
    s.cancel = clamp01(-dx / CANCEL_DISTANCE);
    s.lock = clamp01(s.lock - 0.12);
  }
  if (s.phase === "recording" && s.lock >= 1) lockRecording(s);
}

function lockRecording(s: RecorderState): void {
  'worklet';
  s.phase = "locked";
  s.lockPop = 0.6;
  s.lockPopVel = 0;
  s.events.push({ type: "lock" });
}

// Finger lifts. Before the press delay this is a tap: start a locked
// recording so the flow has a no-drag path (keyboard and screen-reader
// friendly). During recording, a full cancel discards, otherwise the take
// is sent with its duration and the samples that were on screen.
export function recorderPressEnd(s: RecorderState): void {
  'worklet';
  if (s.phase === "pressing") {
    // Tap: begin recording already locked.
    s.phase = "locked";
    s.recAt = s.t;
    s.seconds = 0;
    s.levels = [];
    s.lastSample = 0;
    s.bars = new Array(BAR_COUNT).fill(0.07);
    s.lockPop = 0.6;
    s.lockPopVel = 0;
    s.events.push({ type: "start" }, { type: "lock" });
    return;
  }
  if (s.phase !== "recording") return;
  if (s.cancel >= 1) cancelRecording(s);
  else sendRecording(s);
}

export function recorderLockedSend(s: RecorderState): void {
  'worklet';
  if (s.phase === "locked") sendRecording(s);
}

export function recorderLockedCancel(s: RecorderState): void {
  'worklet';
  if (s.phase === "locked") cancelRecording(s);
}

function sendRecording(s: RecorderState): void {
  'worklet';
  s.phase = "sending";
  s.anim = 0;
  s.events.push({ type: "send", seconds: s.seconds, samples: s.levels.slice() });
}

function cancelRecording(s: RecorderState): void {
  'worklet';
  s.phase = "cancelling";
  s.anim = 0;
  s.events.push({ type: "cancel", seconds: s.seconds });
}

function resetToIdle(s: RecorderState): void {
  'worklet';
  s.phase = "idle";
  s.cancel = 0;
  s.lock = 0;
  s.anim = 0;
  s.seconds = 0;
  s.levels = [];
  s.bars = new Array(BAR_COUNT).fill(0.07);
}

// Advance the sim. The caller passes real dt (already scaled for slow
// motion). With reduced motion the morphs finish instantly but the data
// path (sampling, timer, events) is unchanged.
export function stepRecorder(s: RecorderState, dt: number): void {
  'worklet';
  s.t += dt;

  if (s.phase === "pressing" && s.t - s.pressAt >= PRESS_DELAY_S) {
    s.phase = "recording";
    s.recAt = s.t;
    s.seconds = 0;
    s.levels = [];
    s.lastSample = 0;
    s.bars = new Array(BAR_COUNT).fill(0.07);
    s.events.push({ type: "start" });
  }

  if (s.phase === "recording" || s.phase === "locked") {
    s.seconds = s.t - s.recAt;
    while (s.seconds - s.lastSample >= BAR_SAMPLE_S) {
      s.lastSample += BAR_SAMPLE_S;
      const level = levelAt(s.lastSample, s.seed);
      s.levels.push(level);
      s.bars.push(level);
      if (s.bars.length > BAR_COUNT) s.bars.shift();
    }
    if (s.seconds >= MAX_SECONDS) sendRecording(s);
  }

  if (s.phase === "cancelling" || s.phase === "sending") {
    s.anim += dt / (s.phase === "sending" ? SEND_ANIM_S : CANCEL_ANIM_S);
    if (s.anim >= 1 || s.reduced) resetToIdle(s);
  }

  // Mic springs up while recording and settles back after. The lock capsule
  // pops once on lock. Reduced motion: no overshoot, land on target.
  const micTarget = s.phase === "recording" || s.phase === "locked" ? 1.22 : 1;
  if (s.reduced) {
    s.micScale = micTarget;
    s.micVel = 0;
    s.lockPop = 0;
    s.lockPopVel = 0;
  } else {
    [s.micScale, s.micVel] = spring(s.micScale, s.micVel, micTarget, dt, 240, 15);
    [s.lockPop, s.lockPopVel] = spring(s.lockPop, s.lockPopVel, 0, dt, 160, 13);
  }
}

// Waveform bar segment for drawing: i runs 0 (oldest) to BAR_COUNT-1
// (newest). Heights ease in from the newest edge so fresh audio "grows".
export function barSegment(s: RecorderState, i: number): { x: number; y0: number; y1: number; level: number } {
  'worklet';
  const slot = (WAVE_X1 - WAVE_X0) / BAR_COUNT;
  const x = WAVE_X0 + slot * (i + 0.5);
  let level = s.bars[i] ?? 0.07;
  if (s.phase === "cancelling" || s.phase === "sending") level *= 1 - clamp01(s.anim);
  const half = 2 + level * 13;
  return { x, y0: WAVE_CY - half, y1: WAVE_CY + half, level };
}

// Horizontal drift applied to the waveform while cancelling: the take
// slides away to the left and flushes red (tint alpha returned too).
export function cancelWash(s: RecorderState): { dx: number; alpha: number } {
  'worklet';
  if (s.phase !== "cancelling") return { dx: 0, alpha: 0 };
  const f = clamp01(s.anim);
  return { dx: -f * 90, alpha: f * 0.5 };
}

// Palette and small geometry for the Voice Recorder. The bar borrows the
// site's light Geist card tones; the recording accent is a signal red.

export const REC_BACKGROUND = "#f6f8f4";
export const REC_BAR_BG = "#ffffff";
export const REC_BAR_BORDER = "#d5e1d2";
export const REC_GREEN = "#193f30"; // mic + send
export const REC_GREEN_SOFT = "#e6edde";
export const REC_WAVE = "#31533e";
export const REC_RED = "#e5484d";
export const REC_RED_SOFT = "#fbe9e7";
export const REC_TEXT = "#4b6053";
export const REC_TEXT_FAINT = "#8aa092";
export const REC_LOCK_BG = "#193f30";

import React, { useEffect, useRef, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { VoiceRecorder, type VoiceMessage } from "./VoiceRecorder";
import { formatClock } from "./recorderMath";
import { REC_GREEN, REC_GREEN_SOFT, REC_TEXT, REC_WAVE } from "./recorderDesign";

type Sent = VoiceMessage & { id: number };

// A sent voice message: play sweeps a playhead across the recorded samples.
// Playback is simulated on a timer; this demo never touches the microphone.
function VoicePill({ msg }: { msg: Sent }) {
  const [played, setPlayed] = useState(0);
  const [playing, setPlaying] = useState(false);
  useEffect(() => {
    if (!playing) return;
    const id = setInterval(() => {
      setPlayed((p) => {
        if (p + 0.1 >= msg.seconds) {
          setPlaying(false);
          return 0;
        }
        return p + 0.1;
      });
    }, 100);
    return () => clearInterval(id);
  }, [playing, msg.seconds]);
  const bars = msg.samples.filter((_, i) => i % 2 === 0).slice(-24);
  const progress = msg.seconds > 0 ? played / msg.seconds : 0;
  return (
    <View style={{ flexDirection: "row", alignItems: "center", gap: 10, alignSelf: "flex-end", backgroundColor: REC_GREEN_SOFT, borderRadius: 20, paddingVertical: 10, paddingHorizontal: 14, maxWidth: 280 }}>
      <Pressable accessibilityRole="button" accessibilityLabel={playing ? "Pause voice message" : "Play voice message"} onPress={() => setPlaying((v) => !v)} style={{ width: 30, height: 30, borderRadius: 15, backgroundColor: REC_GREEN, alignItems: "center", justifyContent: "center" }}>
        {playing ? (
          <View style={{ flexDirection: "row", gap: 3 }}>
            <View style={{ width: 3, height: 10, backgroundColor: "#fff", borderRadius: 1.5 }} />
            <View style={{ width: 3, height: 10, backgroundColor: "#fff", borderRadius: 1.5 }} />
          </View>
        ) : (
          <View style={{ width: 0, height: 0, marginLeft: 2, borderLeftWidth: 9, borderLeftColor: "#fff", borderTopWidth: 6, borderTopColor: "transparent", borderBottomWidth: 6, borderBottomColor: "transparent" }} />
        )}
      </Pressable>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 2, height: 26 }}>
        {bars.map((level, i) => (
          <View key={i} style={{ width: 2.6, borderRadius: 1.3, height: 3 + level * 20, backgroundColor: i / bars.length <= progress ? REC_GREEN : REC_WAVE, opacity: i / bars.length <= progress ? 1 : 0.55 }} />
        ))}
      </View>
      <Text style={{ color: REC_TEXT, fontSize: 12, fontVariant: ["tabular-nums"] }}>{formatClock(played > 0 ? played : msg.seconds)}</Text>
    </View>
  );
}

export default function Example({ onFeedback }: { onFeedback?: (event: string) => void }) {
  const [messages, setMessages] = useState<Sent[]>([]);
  const [slow, setSlow] = useState(false);
  const idRef = useRef(0);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? REC_GREEN : "#ffffff", borderColor: on ? REC_GREEN : "#d5e1d2",
  });
  const chipText = (on: boolean) => ({ color: on ? "#ffffff" : REC_TEXT, fontSize: 12, fontWeight: "600" as const });
  return (
    <View style={{ alignItems: "center", gap: 12, paddingVertical: 14 }}>
      <View style={{ width: 360, minHeight: 190, justifyContent: "flex-end", gap: 8, paddingHorizontal: 8 }}>
        <View style={{ alignSelf: "flex-start", backgroundColor: "#ffffff", borderRadius: 18, borderWidth: 1, borderColor: "#d5e1d2", paddingVertical: 9, paddingHorizontal: 13 }}>
          <Text style={{ color: "#1d2b23", fontSize: 14 }}>send the voice note when it works</Text>
        </View>
        {messages.map((m) => <VoicePill key={m.id} msg={m} />)}
      </View>
      <VoiceRecorder
        slowMotion={slow}
        onSend={(msg) => setMessages((list) => [...list.slice(-3), { ...msg, id: ++idRef.current }])}
        onFeedback={(event) => onFeedback?.(event)}
      />
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="button" onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={chipText(slow)}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="button" onPress={() => setMessages([])} style={chip(false)}>
          <Text style={chipText(false)}>Reset</Text>
        </Pressable>
      </View>
      <Text style={{ color: REC_TEXT, fontSize: 12, textAlign: "center", maxWidth: 320 }}>
        Hold the mic to record. Slide left to cancel, drag up to lock. Tap the mic to record hands free. Audio levels are simulated.
      </Text>
    </View>
  );
}
